import { test } from "node:test";
import assert from "node:assert/strict";
import { FirmwareRollout, MAX_FAILURES } from "../src/firmware/rollout.ts";
import { rolloutReport } from "../src/firmware/report.ts";
import type { Device, DeviceRegistry } from "../src/firmware/registry.ts";

// A fake that behaves like the real registry: rows are stored as copies, so changing an
// object you read does nothing until you save() it. (A Map of live objects would hide that.)
function fakeRegistry(devices: Device[]): DeviceRegistry & { row(id: string): Device } {
    const rows = new Map(devices.map((d) => [d.id, structuredClone(d)]));
    return {
        row: (id) => structuredClone(rows.get(id)!),
        get: async (id) => (rows.has(id) ? structuredClone(rows.get(id)!) : null),
        listByCohort: async (cohort) => [...rows.values()].filter((d) => d.cohort === cohort).map((d) => structuredClone(d)),
        save: async (d) => void rows.set(d.id, structuredClone(d)),
    };
}

const device = (id: string, extra: Partial<Device> = {}): Device => ({
    id,
    cohort: "thermo-eu",
    online: true,
    firmware: "4.1.0",
    status: "idle",
    targetVersion: null,
    failures: 0,
    lastError: null,
    lastOfferedAt: null,
    ...extra,
});

function setup(devices: Device[]) {
    const registry = fakeRegistry(devices);
    return { registry, rollout: new FirmwareRollout(registry, () => new Date("2026-11-19T03:00:00Z")) };
}

test("the next batch skips offline devices and devices already on the version", async () => {
    const { registry, rollout } = setup([device("t1"), device("t2", { online: false }), device("t3", { firmware: "4.2.0" }), device("t4"), device("t5")]);
    const batch = await rollout.nextBatch("thermo-eu", "4.2.0", 2);
    assert.deepEqual(batch.map((d) => d.id), ["t1", "t4"]);
    assert.deepEqual([registry.row("t1").status, registry.row("t1").targetVersion], ["updating", "4.2.0"]);
    assert.equal(registry.row("t5").status, "idle");
});

test("a successful install records the new firmware", async () => {
    const { registry, rollout } = setup([device("t1")]);
    await rollout.nextBatch("thermo-eu", "4.2.0", 10);
    await rollout.recordResult("t1", "4.2.0", { ok: true });
    assert.deepEqual([registry.row("t1").firmware, registry.row("t1").status], ["4.2.0", "idle"]);
});

test("a failed install is remembered with its error", async () => {
    const { registry, rollout } = setup([device("t1")]);
    await rollout.nextBatch("thermo-eu", "4.2.0", 10);
    await rollout.recordResult("t1", "4.2.0", { ok: false, error: "checksum mismatch" });
    const row = registry.row("t1");
    assert.deepEqual([row.failures, row.lastError, row.status, row.targetVersion], [1, "checksum mismatch", "idle", null]);
});

test(`a device that fails ${MAX_FAILURES} times in a row is quarantined and not offered again`, async () => {
    const { registry, rollout } = setup([device("t1"), device("t2", { firmware: "4.2.0" })]);
    for (let i = 0; i < MAX_FAILURES; i++) {
        await rollout.nextBatch("thermo-eu", "4.2.0", 10);
        await rollout.recordResult("t1", "4.2.0", { ok: false, error: "flash write failed" });
    }
    console.log("t1 in the registry after", MAX_FAILURES, "failures:", registry.row("t1"));
    assert.equal(registry.row("t1").status, "quarantined");
    assert.deepEqual(await rollout.nextBatch("thermo-eu", "4.2.0", 10), []);
});

test("a success after a failure clears the failure count", async () => {
    const { registry, rollout } = setup([device("t1", { failures: 2, lastError: "timeout" })]);
    await rollout.nextBatch("thermo-eu", "4.2.0", 10);
    await rollout.recordResult("t1", "4.2.0", { ok: true });
    assert.deepEqual([registry.row("t1").failures, registry.row("t1").lastError], [0, null]);
});

test("a late report from an earlier rollout is ignored", async () => {
    const { registry, rollout } = setup([device("t1")]);
    await rollout.nextBatch("thermo-eu", "4.2.0", 10);
    await rollout.recordResult("t1", "4.1.9", { ok: false, error: "old" });
    assert.deepEqual([registry.row("t1").status, registry.row("t1").failures], ["updating", 0]);
    await assert.rejects(rollout.recordResult("nope", "4.2.0", { ok: true }), /unknown device nope/);
});

test("the rollout report shows updated, retrying and quarantined devices", async () => {
    const { registry, rollout } = setup([device("t1"), device("t2"), device("t3", { failures: 2 }), device("t4")]);
    await rollout.nextBatch("thermo-eu", "4.2.0", 10);
    await rollout.recordResult("t1", "4.2.0", { ok: true });
    await rollout.recordResult("t2", "4.2.0", { ok: false, error: "low battery" });
    await rollout.recordResult("t3", "4.2.0", { ok: false, error: "flash write failed" });
    assert.deepEqual(await rolloutReport(registry, "thermo-eu", "4.2.0"), { total: 4, onVersion: 1, updating: 1, retrying: 1, quarantined: 1 });
});
